mapper.sql:
WHERE P.sys_id = #{sysId} AND P.del_yn = 'N'

    AND (P.prd_nm LIKE CONCAT('%', #{searchKeyword}, '%') OR P.prd_cd LIKE CONCAT('%', #{searchKeyword}, '%'))


    AND P.cte_idx = #{cteIdx}

mapper.select:
SELECT P.idx AS "idx", P.sys_id AS "sysId", P.prd_cd AS "prdCd", P.prd_nm AS "prdNm", P.cte_idx AS "cteIdx", C.cte_nm AS "cteNm", P.prd_expl AS "prdExpl", P.use_yn AS "useYn", (SELECT COUNT(*) FROM TN_PRD_SKU_M001 S WHERE S.prd_idx = P.idx AND S.del_yn = 'N') AS "skuCount" FROM TN_PRD_M001 P LEFT JOIN TN_PRD_CTE_M001 C ON P.cte_idx = C.idx
ORDER BY P.idx DESC
LIMIT #{offset}, #{pageSize}
